580,"height":140,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"The gym turns into a bookstore March 10–12. Family night is Wednesday until 7 PM with pizza by donation. Volunteers still needed for Tuesday morning — sign up at the front desk.","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#334155","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"text_mvv4693p13ceqqu5","type":"text","x":90,"y":940,"width":660,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"🥗 LUNCH MENU CHANGES","fontSize":30,"fontFamily":"Quicksand","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#1E40AF","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693p13dasgsz","type":"text","x":90,"y":1000,"width":660,"height":130,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"New menu starts after spring break: Taco Tuesday gains a veggie option, and Friday is now “build your own grain bowl” day. Full menu on the school portal.","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#334155","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"rect_mvv4693p13ejh6vo","type":"rect","x":800,"y":350,"width":350,"height":540,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"fill":"#FEF9C3","stroke":"transparent","strokeWidth":0,"cornerRadius":20},{"id":"text_mvv4693p13fw4zo1","type":"text","x":840,"y":385,"width":270,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"DATES TO KNOW","fontSize":26,"fontFamily":"Quicksand","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#854D0E","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693p13g2hyt7","type":"text","x":840,"y":445,"width":270,"height":420,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Mar 10–12 · Book Fair\nMar 13 · No school\nMar 16–20 · Conferences\nMar 23–27 · Spring break\nApr 2 · Science Night\nApr 10 · Fun Run","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#57430A","align":"left","lineHeight":2,"letterSpacing":0},{"id":"rect_mvv4693p13hgcbqv","type":"rect","x":800,"y":920,"width":350,"height":300,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"fill":"#DCFCE7","stroke":"transparent","strokeWidth":0,"cornerRadius":20},{"id":"text_mvv4693p13iwklhx","type":"text","x":840,"y":955,"width":270,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"🏃 FUN RUN SPONSORS","fontSize":26,"fontFamily":"Quicksand","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#166534","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693p13jy4ndf","type":"text","x":840,"y":1015,"width":270,"height":180,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Pledges are at $4,180 of our $6,000 goal. Every dollar funds new playground balls, art supplies and field trips. Pledge forms went home Monday!","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill"