('0fc1f83a-2191-476b-a87f-cc7b2dcc428c','press-release','Press Release','document',1240,1754,'[{"id":"p1","background":{"type":"solid","color":"#FFFFFF"},"elements":[{"id":"text_mvv4693p14vcg2kf","type":"text","x":90,"y":100,"width":1060,"height":70,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"FERNWAY","fontSize":54,"fontFamily":"Bodoni Moda","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#111827","align":"center","lineHeight":1.25,"letterSpacing":0},{"id":"line_mvv4693p14wyuaao","type":"line","x":240,"y":185,"width":760,"height":0,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"stroke":"#111827","strokeWidth":3,"dashed":false,"arrowStart":false,"arrowEnd":false},{"id":"line_mvv4693p14x9fuh8","type":"line","x":240,"y":193,"width":760,"height":0,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"stroke":"#111827","strokeWidth":1,"dashed":false,"arrowStart":false,"arrowEnd":false},{"id":"text_mvv4693p14yfo6x9","type":"text","x":90,"y":210,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"URBAN MOBILITY · PRESS OFFICE","fontSize":19,"fontFamily":"Inter","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#6B7280","align":"center","lineHeight":1.25,"letterSpacing":6},{"id":"rect_mvv4693p14zhs9ik","type":"rect","x":90,"y":300,"width":340,"height":55,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"fill":"#991B1B","stroke":"transparent","strokeWidth":0,"cornerRadius":6},{"id":"text_mvv4693p150c5vnp","type":"text","x":110,"y":313,"width":300,"height":35,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"FOR IMMEDIATE RELEASE","fontSize":18,"fontFamily":"Inter","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#FFFFFF","align":"center","lineHeight":1.25,"letterSpacing":1},{"id":"text_mvv4693p151n61r2","type":"text","x":90,"y":400,"width":1060,"height":120,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Fernway passes 40,000 drivers as it expands\nparking prediction to three new cities","fontSize":44,"fontFamily":"Playfair Display","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#111827","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693p152r498g","type":"text","x":90,"y":550,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Denver, Austin and Philadelphia join the platform in June; company predicts a free 12-minute average search time.","fontSize":25,"fontFamily":"Lora","bold":false,"italic":true,"underline":false,"strike":false,"uppercase":false,"fill":"#4B5563","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"line_mvv4693p1536gslj","type":"line","x":90,"y":620,"width":1060,"height":0,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"stroke":"#E5E7EB","strokeWidth":2,"dashed":false,"arrowStart":false,"arrowEnd":false},{"id":"text_mvv4693p154zoea9","type":"text","x":90,"y":660,"width":1060,"height":190,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Brooklyn, NY — March 5, 2026 — Fernway, the parking prediction app that tells drivers where a spot will open before they arrive, today announced it has passed 40,000 monthly active drivers across 12 cities. The company also confirmed expansion to Denver, Austin and Philadelphia this June, funded entirely by its city-partnership model rather than driver fees.","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#374151","align":"left","lineHeight":1.75,"letterSpacing":0},{"id":"text_mvv4693p1552we2q","type":"text","x":90,"y":880,"width":1060,"height":160,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"“Parking is a math problem, not a luck problem,” said co-founder and CEO Ines Ward. “Every circling car is a small tax on the whole street. When 40,000 people stop circling, the block gets quieter, faster and safer — that’s the mission, and these three cities double our reach.”","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#374151","align":"left","lineHeight":1.75,"letterSpacing":0},{"id":"text_mvv4693p156kerpb","type":"text","x":90,"y":1070,"width":1060,"height":190,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Fernway’s model uses anonymized curbside sensors and historical turnover data to predict where spaces will free up within a 12-minute arrival window, with 87% accuracy in its densest market. The app remains free for drivers; cities pay for the congestion analytics layer, and nine of Fernway’s twelve municipal partners have renewed for a second year.","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#374151","align":"left","lineHeight":1.75,"letterSpacing":0},{"id":"text_mvv4693p157by50p","type":"text","x":90,"y":1300,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"About Fernway","fontSize":30,"fontFamily":"Playfair Display","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#111827","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693p158myfhp","type":"text","x":90,"y":1355,"width":1060,"height":120,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Founded in 2023 by Ines Ward and Tom Okafor, Fernway works with cities to reduce curbside congestion through prediction. The company is remote-first with a 22-person team across Brooklyn and Oslo.","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#4B5563","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"line_mvv4693p159vudhi","type":"line","x":90,"y":1500,"width":1060,"height":0,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"stroke":"#E5E7EB","strokeWidth":2,"dashed":false,"arrowStart":false,"arrowEnd":false},{"id":"text_mvv4693p15amfpz1","type":"text","x":90,"y":1530,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Press contact: Dana Kim · press@fernway.app · +1 (555) 903-2210","fontSize":21,"fontFamily":"Inter","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#991B1B","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693p15bypj8d","type":"text","x":90,"y":1580,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"###","fontSize":24,"fontFamily